/* From Uiverse.io by cssbuttons-io - Tags: button */
.__UIV_SCOPE__ button {
 --color: #560bad;
 font-family: inherit;
 display: inline-block;
 width: 8em;
 height: 2.6em;
 line-height: 2.5em;
 margin: 20px;
 position: relative;
 overflow: hidden;
 border: 2px solid var(--color);
 transition: color .5s;
 z-index: 1;
 font-size: 17px;
 border-radius: 6px;
 font-weight: 500;
 color: var(--color);
}

.__UIV_SCOPE__ button:before {
 content: "";
 position: absolute;
 z-index: -1;
 background: var(--color);
 height: 150px;
 width: 200px;
 border-radius: 50%;
}

.__UIV_SCOPE__ button:hover {
 color: #fff;
}

.__UIV_SCOPE__ button:before {
 top: 100%;
 left: 100%;
 transition: all .7s;
}

.__UIV_SCOPE__ button:hover:before {
 top: -30px;
 left: -30px;
}

.__UIV_SCOPE__ button:active:before {
 background: #3a0ca3;
 transition: background 0s;
}
